$root='<WINDOWS_FIXTURE>';$ErrorActionPreference='Stop';foreach($e in @(Get-Content -Raw (Join-Path $root 'build-input-hashes.json')|ConvertFrom-Json)){if((Get-FileHash (Join-Path $root $e.path) -Algorithm SHA256).Hash -ne $e.sha256){throw 'build input transfer mismatch'}};$tokens=$null;$errors=$null;$null=[System.Management.Automation.Language.Parser]::ParseFile((Join-Path $root 'build.ps1'),[ref]$tokens,[ref]$errors);if($errors.Count -gt 0){throw ($errors|Out-String)};& (Join-Path $root 'build.ps1')